-- A bulk action on a user's notifications (today: clearing the inbox) is a
-- durable record the server works through in chunks. Each chunk commits its
-- state changes, their ledger rows and the action's cursor in one
-- transaction, so a crash or deploy resumes from the cursor and applies
-- nothing twice.
SET lock_timeout = '5s';

CREATE TABLE notification_bulk_action (
    -- Generated by the caller: sending the same action twice creates it once.
    id UUID PRIMARY KEY,
    user_id TEXT NOT NULL,
    -- What the action covers, frozen when it was created. Owned by the caller.
    scope JSONB NOT NULL,
    -- Only notifications created at or before this time are changed.
    as_of TIMESTAMPTZ NOT NULL DEFAULT now(),
    status TEXT NOT NULL DEFAULT 'applying' CHECK (
        status IN ('applying', 'done', 'undoing', 'undone', 'failed')
    ),
    -- Where the next chunk starts. Owned by the caller.
    cursor JSONB,
    -- Caller-counted units applied so far (inbox rows).
    units INTEGER NOT NULL DEFAULT 0,
    -- Notifications the action marked done, and how many an undo reopened.
    applied INTEGER NOT NULL DEFAULT 0,
    restored INTEGER NOT NULL DEFAULT 0,
    -- Bumps on every change, so readers can drop stale updates.
    revision BIGINT NOT NULL DEFAULT 0,
    -- The worker holding the action. A chunk commits only under its token.
    lease_token UUID,
    lease_expires_at TIMESTAMPTZ,
    -- Claims of a stalled action since its last committed chunk.
    attempts SMALLINT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at TIMESTAMPTZ
);

CREATE INDEX idx_notification_bulk_action_user
    ON notification_bulk_action (user_id, created_at DESC);

-- Finds running actions whose worker stopped renewing its lease.
CREATE INDEX idx_notification_bulk_action_stalled
    ON notification_bulk_action (lease_expires_at)
    WHERE status IN ('applying', 'undoing');

-- Finished actions are deleted a day later, which removes their ledger.
CREATE INDEX idx_notification_bulk_action_finished
    ON notification_bulk_action (finished_at)
    WHERE finished_at IS NOT NULL;

-- The ledger: one row per notification an action changed, with the state to
-- restore on undo.
CREATE TABLE notification_bulk_action_item (
    action_id UUID NOT NULL REFERENCES notification_bulk_action (id) ON DELETE CASCADE,
    notification_id UUID NOT NULL,
    -- The notification was unseen before the action; otherwise it was seen.
    was_unseen BOOLEAN NOT NULL,
    -- The caller's grouping of the notification, returned on undo.
    group_key TEXT NOT NULL,
    -- An undo has handled this row.
    undone BOOLEAN NOT NULL DEFAULT FALSE,
    PRIMARY KEY (action_id, notification_id)
);

-- The bulk action that last set this notification's state. Any other state
-- change clears it, so an undo reopens only what its action still owns.
ALTER TABLE user_notification ADD COLUMN done_by UUID;

CREATE FUNCTION clear_user_notification_done_by() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.state IS DISTINCT FROM OLD.state
        AND NEW.done_by IS NOT DISTINCT FROM OLD.done_by THEN
        NEW.done_by := NULL;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_clear_user_notification_done_by
BEFORE UPDATE OF state ON user_notification
FOR EACH ROW
WHEN (OLD.done_by IS NOT NULL)
EXECUTE FUNCTION clear_user_notification_done_by();
